function renderWeeklyVacations(){
 const [week]=weeklyVacations(workspace,workspace.activeWeek),upcoming=upcomingVacations(workspace,scheduleToday());
 $('vacationThisWeekDates').textContent=displayDate(week.from)+' through '+displayDate(week.to);
 $('vacationThisWeekList').innerHTML=week.guards.length?week.guards.map(g=>'<div class="vacation-guard"><b>'+esc(g.guard)+'</b><span>'+g.ranges.map(r=>displayDate(r.from)+(r.from===r.to?'':' through '+displayDate(r.to))).join(' · ')+'</span></div>').join(''):'<p class="muted">No vacations recorded.</p>';
 $('vacationNextWeekDates').textContent='From today · '+displayDate(upcoming.from)+' through '+displayDate(upcoming.to);
 $('vacationNextWeekList').innerHTML=upcoming.guards.length?upcoming.guards.map(g=>'<div class="vacation-guard"><b>'+esc(g.guard)+'</b><span>'+displayDate(g.from)+(g.from===g.to?'':' through '+displayDate(g.to))+'</span><span class="vacation-countdown">'+(g.daysUntil===0?'Starts today':g.daysUntil===1?'Starts tomorrow':'Starts in '+g.daysUntil+' days')+'</span></div>').join(''):'<p class="muted">No vacations starting in the next 14 days.</p>';
}

function renderWeeklyLeave(){
 $('weeklyLeavePanel').hidden=workspace.mode!=='weekly';
 const groups=new Map(),add=(guard,type,day)=>{if(!guard||day<0||day>6)return;const k=guard+'|'+type;if(!groups.has(k))groups.set(k,{guard,type,days:new Set()});groups.get(k).days.add(day);};
 for(const e of state.events||[])add(e.guard,e.type,e.day);
 for(const v of workspace.vacations||[])for(let day=0;day<7;day++)if(DATES[day]>=v.from&&DATES[day]<=v.to)add(v.guard,'Vacation',day);
 $('weeklyLeaveList').innerHTML=groups.size?[...groups.values()].sort((a,b)=>a.guard.localeCompare(b.guard)||a.type.localeCompare(b.type)).map(g=>'<div class="change"><span><b>'+esc(g.guard)+'</b> · '+esc(leaveTypeLabel(g.type))+'<br>'+leaveDateRanges(g.days)+'</span></div>').join(''):'<p class="muted">No leave recorded for this week.</p>';
}

function leaveDateRanges(days){const sorted=[...days].sort((a,b)=>a-b),ranges=[];for(const day of sorted){const last=ranges.at(-1);if(last&&day===last[1]+1)last[1]=day;else ranges.push([day,day]);}return ranges.map(([from,to])=>displayDate(DATES[from])+(from===to?'':' through '+displayDate(DATES[to]))).join(' · ');}

function renderHoursExplanation(guard,day,scheduled,worked){
 const week=workspace.activeWeek,active=workspace.mode==='weekly'&&!state.isTest;
 const records=active?(workspace.payrollTransfers||[]).filter(t=>(!guard||t.guard===guard)&&((t.fromWeek===week&&(day==='all'||t.day===+day))||(t.toWeek===week&&!workspace.weeks[t.fromWeek]?.isTest&&(day==='all'||+day===6)))):[];
 const incoming=records.filter(t=>t.toWeek===week).reduce((n,t)=>n+t.hours,0),outgoing=records.filter(t=>t.fromWeek===week).reduce((n,t)=>n+t.hours,0),correction=worked-(scheduled+incoming-outgoing);
 $('hoursExplanation').innerHTML='<h3>Where these hours come from</h3><div class="hours-equation"><span>On this schedule <b>'+num(scheduled)+' hrs</b></span><span>+ From other weeks <b>'+num(incoming)+' hrs</b></span><span>− Counted in other weeks <b>'+num(outgoing)+' hrs</b></span>'+(Math.abs(correction)>.001?'<span>Overlap reconciliation <b>'+num(correction)+' hrs</b></span>':'')+'<span class="result">= Payroll worked <b>'+num(worked)+' hrs</b></span></div><p>'+esc(guard||'All guards')+' · '+(day==='all'?'Whole week':DAYS[+day])+'. Daily totals under Third Platoon follow the schedule. Payroll totals include saved week transfers. Leave and pay adjustments are separate; OT is already part of worked hours.</p>'+(records.length?'<details open><summary>Transfer details ('+records.length+')</summary><ul>'+records.map(t=>'<li><b>'+esc(t.guard)+' · '+(t.toWeek===week?'+':'−')+num(t.hours)+' hrs</b> · W-E '+displayDate(t.fromWeek)+' → W-E '+displayDate(t.toWeek)+' · '+esc(t.post)+' · '+fmt(t.start)+'–'+fmt(t.end)+'<br>'+esc(t.note)+'</li>').join('')+'</ul></details>':'<p>No payroll transfers affect this selection.</p>');
}

async function recheckVacations(){
 try{
  if(workspace.mode!=='weekly')throw Error('Choose a weekly schedule before rechecking vacations.');
  if(activeInline){closeInlineCell();if(activeInline||$('attendanceEditor').open)return;}if(activeRowField){closeRowField();if(activeRowField)return;}
  await savesFinished();if(!$('saveFailure').classList.contains('hidden'))throw Error('Saving is paused. Reload the latest schedule before rechecking vacations.');
  const end=workspace.activeWeek;document.body.inert=true;
  const result=await api('/api/recheck-vacations',{method:'POST',body:JSON.stringify({week:end})});
  window.__BOOT={workspace:structuredClone(result.workspace),revision:result.revision};workspace=result.workspace;workspace.activeWeek=end;workspace.mode='weekly';history=[];STAFF.splice(0,STAFF.length,...activeGuardNames(workspace));showPage(page);
  status(result.openedShifts?'Vacations rechecked. '+result.openedShifts+' shift cells now need coverage.':'Vacations are up to date. Existing coverage kept.');
 }catch(e){status(e.message,true);}finally{document.body.inert=false;}
}
$('recheckVacationsCoverage').onclick=recheckVacations;

function renderLeaveTypes(){
 $('builtInLeaveTypes').textContent='Included: '+BUILTIN_ATTENDANCE_TYPES.filter(t=>!t.startsWith('Return to work')).map(leaveTypeLabel).join(' · ');
 $('customLeaveTypes').innerHTML=customLeaveTypes(workspace).map((t,i)=>'<div class="change"><b>'+esc(t.name)+'</b><button data-remove-leave-type="'+i+'">Remove type</button></div>').join('');
 $('customLeaveTypes').querySelectorAll('[data-remove-leave-type]').forEach(button=>button.onclick=()=>updateLeaveTypes(()=>removeLeaveType(workspace,customLeaveTypes(workspace)[+button.dataset.removeLeaveType].name),'Leave type removed from new selections. Saved leave records kept.'));
}
async function updateLeaveTypes(change,message){try{await savesFinished();const next=change();await saveBlocking(next,'Updated leave types');workspace=next;render();$('leaveTypeStatus').textContent=message;$('leaveTypeStatus').className='muted';return true;}catch(e){renderLeaveTypes();$('leaveTypeStatus').textContent=e.message;$('leaveTypeStatus').className='error';return false;}}
$('addLeaveType').onclick=async()=>{if(await updateLeaveTypes(()=>saveLeaveType(workspace,{name:$('newLeaveTypeName').value}),'Leave type saved. It is available in Attendance.'))$('newLeaveTypeName').value='';};
$('manageLeaveTypes').onclick=()=>{cancelAttendanceChange();showPage('coverage');$('leaveSettings').open=$('leaveTypesPanel').open=true;$('newLeaveTypeName').focus();};

let leaveEntryOptions=[];
function loadLeaveEntryShifts(){const guard=$('leaveEntryGuard').value,seen=new Set();leaveEntryOptions=[];for(const target of ledger(state).filter(r=>r.guard===guard&&!r.paidHoliday)){const id=segmentKey(target);if(seen.has(id))continue;const parts=linkedParts(state,target);for(const part of parts)seen.add(segmentKey(part));seen.add(id);leaveEntryOptions.push({target,start:parts.length>1?Math.min(...parts.map(p=>p.start)):target.start,end:parts.length>1?Math.max(...parts.map(p=>p.end)):target.end,linked:parts.length>1});}$('leaveEntryShift').innerHTML=leaveEntryOptions.map((o,i)=>'<option value="'+i+'">'+DAYS[o.target.day]+' '+DATES[o.target.day].slice(5)+' · '+esc(o.target.post)+' · '+fmt(o.start)+'–'+fmt(o.end)+(o.linked?' · Both parts':'')+'</option>').join('');$('continueLeaveEntry').disabled=!leaveEntryOptions.length;$('leaveEntryMessage').textContent=leaveEntryOptions.length?'Choose a shift, then select the leave type.':'No assigned shifts for this guard in this week. Use the vacation date range for future vacation.';}
$('addLeaveEntry').onclick=()=>{$('leaveEntryGuard').innerHTML=STAFF.map(n=>'<option>'+esc(n)+'</option>').join('');$('leaveEntryGuard').value=STAFF[0]||'';loadLeaveEntryShifts();$('leaveEntryEditor').showModal();};$('leaveEntryGuard').onchange=loadLeaveEntryShifts;$('closeLeaveEntry').onclick=()=>$('leaveEntryEditor').close();$('continueLeaveEntry').onclick=()=>{const option=leaveEntryOptions[+$('leaveEntryShift').value];if(!option)return;$('leaveEntryEditor').close();openAttendance(option.target);};
$('printManagerPage').onclick=()=>{document.body.classList.add('print-manager-section');$('managerApp').setAttribute('data-print-section',page);window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('print-manager-section'));

$('openVacationForm').onclick=()=>{$('vacationFormPanel').open=true;$('vacationFrom').focus();};$('printExportActions').addEventListener('click',()=>{$('printExportMenu').open=false;});

let holidayCreditEditing=null;
function renderHolidayCredits(){const list=holidayCreditBalances(workspace);$('holidayCreditList').innerHTML=list.length?list.map(c=>'<div class="change"><span><b>'+esc(c.guard)+'</b> · '+esc(c.holidayName)+' '+displayDate(c.holidayDate)+'<br>'+(!c.sourceValid?'Original vacation or holiday changed':!c.use?'1 day owed · Available after '+displayDate(c.vacationTo):c.use.status==='APPLIED'?(c.use.mode==='DAY_OFF'?'Day off':'Working · extra holiday hours')+' · '+displayDate(c.use.date):c.use.status==='WAITING_SCHEDULE'?'Scheduled for '+displayDate(c.use.date)+' · Waiting for weekly schedule':'Check assignment · '+displayDate(c.use.date))+'</span>'+(c.sourceValid&&(!c.use||c.use.status!=='APPLIED')?'<button data-use-holiday-credit="'+esc(c.id)+'">'+(c.use?'Change choice':'Use day')+'</button>':'<span class="status saved">Recorded</span>')+(c.use&&c.use.status!=='APPLIED'?'<button data-cancel-holiday-credit="'+esc(c.id)+'">Cancel choice</button>':'')+'</div>').join(''):'<p class="muted">No extra holiday days owed. A checked holiday during a saved vacation creates one day owed.</p>';
 $('holidayCreditList').querySelectorAll('[data-use-holiday-credit]').forEach(b=>b.onclick=()=>{const c=holidayCreditBalances(workspace).find(c=>c.id===b.dataset.useHolidayCredit);if(!c?.sourceValid)return;holidayCreditEditing=c.id;$('holidayCreditContext').textContent=c.guard+' · '+c.holidayName+' · 1 day';$('holidayCreditMode').value=c.use?.mode||'DAY_OFF';const d=new Date(c.vacationTo+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+1);$('holidayCreditDate').min=d.toISOString().slice(0,10);$('holidayCreditDate').value=c.use?.date||d.toISOString().slice(0,10);$('holidayCreditHours').value=c.use?.hours||8;$('holidayCreditNote').value=c.use?.note||'';$('holidayCreditError').textContent='';$('holidayCreditEditor').showModal();});
 $('holidayCreditList').querySelectorAll('[data-cancel-holiday-credit]').forEach(b=>b.onclick=async()=>{try{await savesFinished();const next=cancelHolidayCredit(workspace,b.dataset.cancelHolidayCredit);await saveBlocking(next,'Cancelled pending holiday day choice');workspace=next;render();}catch(e){$('holidayCreditMessage').textContent=e.message;}});
}
$('closeHolidayCredit').onclick=()=>$('holidayCreditEditor').close();$('saveHolidayCredit').onclick=async()=>{try{await savesFinished();const next=useHolidayCredit(workspace,{id:holidayCreditEditing,mode:$('holidayCreditMode').value,date:$('holidayCreditDate').value,hours:Number($('holidayCreditHours').value),note:$('holidayCreditNote').value});await saveBlocking(next,'Recorded extra holiday day for '+holidayCreditEditing);workspace=next;state=structuredClone(workspace.weeks[workspace.activeWeek]);history=[];applyRows(state);$('holidayCreditEditor').close();render();status('Extra holiday day choice saved.');}catch(e){$('holidayCreditError').textContent=e.message;}};

function resetHoursFilters(){$('payGuard').value='';$('payDay').value='all';}
function renderGuardHours(payRows,guard,day,weekNames){
 const names=guard?[guard]:weekNames,totals=guardHoursTotals(payRows,names);
 $('guardHoursSummaryTitle').textContent=(day==='all'?'Guard hours for the week':'Guard hours for '+DAYS[+day])+' · W-E '+displayDate(workspace.activeWeek);
 $('guardHoursSummary').innerHTML=totals.length?'<table class="paytable guard-hours-table"><thead><tr><th>Guard</th><th>Worked hours</th><th>OT (included)</th><th>Leave / holiday</th><th>Corrections</th><th>Total payable</th></tr></thead><tbody>'+totals.map(g=>'<tr><td><button class="row-tool" data-guard-hours="'+esc(g.guard)+'">'+esc(guardLabel(g.guard))+'</button></td><td><strong>'+num(g.worked)+'</strong></td><td>'+num(g.overtime)+'</td><td>'+num(g.paidLeave)+'</td><td>'+num(g.adjustmentHours)+'</td><td>'+num(g.payable)+'</td></tr>').join('')+'<tr><th>Total</th>'+['worked','overtime','paidLeave','adjustmentHours','payable'].map(k=>'<th>'+num(totals.reduce((n,g)=>n+g[k],0))+'</th>').join('')+'</tr></tbody></table>':'<p class="muted">Add guards or scheduled shifts to see weekly hours.</p>';
 $('guardHoursSummary').querySelectorAll('[data-guard-hours]').forEach(b=>b.onclick=()=>{$('payGuard').value=b.dataset.guardHours;render();});
}
$('openGuardWeeklyHours').onclick=()=>{resetHoursFilters();showPage('weekly');$('guardHoursSection').open=true;$('guardHoursSection').scrollIntoView?.({behavior:'smooth',block:'start'});};

$('saveScheduleExcel').onclick=()=>{try{if(activeInline){closeInlineCell();if($('attendanceEditor').open||activeInline)return;}if(activeRowField){closeRowField();if(activeRowField)return;}const filename=downloadScheduleExcel(workspace,state,workspace.mode,workspace.activeWeek);status('Downloaded '+filename);}catch(e){status('Excel download failed: '+e.message,true);}};
